import { createHash } from 'node:crypto';
import type { EventPayload, FailureCode } from '@agent-teams/provider-session-contracts';
export type Fact = EventPayload;
export function record(value: unknown): Record<string, unknown> {
  return value !== null && typeof value === 'object' ? value as Record<string, unknown> : {};
}
export class OutputLimitError extends Error {}
export class Normalizer {
  private streamMessage: string | undefined;
  private readonly blocks = new Map<string, string>();
  private readonly completeIndex = new Map<string, number>();
  private readonly seenWrappers = new Set<string>();
  // Session-lifetime tombstones survive turn resets; never evict and replay a boundary.
  private readonly compactions = new Set<string>();
  private readonly maxBytes: number;
  constructor(maxBytes: number) { this.maxBytes = maxBytes; }
  reset(): void { this.streamMessage = undefined; this.blocks.clear(); this.completeIndex.clear(); this.seenWrappers.clear(); }
  normalize(value: unknown): { facts: Fact[]; terminal?: 'succeeded' | 'failed' | 'unknown'; failure?: FailureCode } {
    const m = record(value);
    if (m.type === 'system' && m.subtype === 'compact_boundary') {
      if (typeof m.uuid !== 'string' || !m.uuid || typeof m.session_id !== 'string' || !m.session_id) {
        return { facts: [{ kind: 'diagnostic', code: 'unknown-event' }] };
      }
      const sourceRef = createHash('sha256').update(JSON.stringify([m.session_id, m.uuid])).digest('hex');
      if (this.compactions.has(sourceRef)) { return { facts: [] }; }
      if ((this.compactions.size + 1) * 64 > this.maxBytes) { throw new OutputLimitError('output-limit'); }
      this.compactions.add(sourceRef);
      const trigger = record(m.compact_metadata).trigger;
      return { facts: [{ kind: 'compaction', sourceRef, reason: trigger === 'auto' ? 'automatic' : trigger === 'manual' ? 'manual' : 'unknown' }] };
    }
    if (m.type === 'stream_event') {return { facts: this.partial(record(m.event)) };}
    if (m.type === 'assistant') {
      if (typeof m.uuid === 'string' && this.seenWrappers.has(m.uuid)) {return { facts: [] };}
      if (typeof m.uuid === 'string') {this.seenWrappers.add(m.uuid);}
      return { facts: this.assistant(record(m.message)) };
    }
    if (m.type === 'user') {return { facts: this.toolResults(record(m.message)) };}
    if (m.type === 'result') {return this.result(m);}
    if (m.type === 'control_request' || m.type === 'control_response') {return { facts: [], terminal: 'unknown', failure: 'unsupported' };}
    return { facts: [{ kind: 'diagnostic', code: 'unknown-event' }] };
  }
  private partial(e: Record<string, unknown>): Fact[] {
    if (e.type === 'message_start') { const id = record(e.message).id; this.streamMessage = typeof id === 'string' ? id : '';  return []; }
    if (this.streamMessage === undefined || this.streamMessage.length === 0 || typeof e.index !== 'number') {return [];}
    const key = `${this.streamMessage}:${e.index}`;
    if (e.type === 'content_block_start') {
      const b = record(e.content_block);
      if (b.type === 'text') {this.blocks.set(`text:${key}`, typeof b.text === 'string' ? b.text : '');}
      if (b.type === 'thinking') {this.blocks.set(`thinking:${key}`, typeof b.thinking === 'string' ? b.thinking : '');}
    }
    const delta = record(e.delta);
    const kind = delta.type === 'text_delta' ? 'text' : delta.type === 'thinking_delta' ? 'thinking' : undefined;
    if (e.type !== 'content_block_delta' || kind === undefined) {return [];}
    const fragment = kind === 'text' ? delta.text : delta.thinking;
    if (typeof fragment !== 'string') {return [];}
    const contentKey = `${kind}:${key}`, text = (this.blocks.get(contentKey) ?? '') + fragment;
    if (Buffer.byteLength(text) > this.maxBytes) {throw new OutputLimitError('output-limit');}
    this.blocks.set(contentKey, text);
    return [{ kind, messageRef: this.streamMessage, block: e.index, text, phase: 'snapshot' }];
  }
  private assistant(message: Record<string, unknown>): Fact[] {
    if (typeof message.id !== 'string' || !Array.isArray(message.content)) {return [];}
    const facts: Fact[] = [];
    let index = this.completeIndex.get(message.id) ?? 0;
    for (const value of message.content) {
      const b = record(value);
      if (b.type === 'text' && typeof b.text === 'string') {facts.push({ kind: 'text', messageRef: message.id, block: index, text: b.text, phase: 'complete' });}
      if (b.type === 'thinking' && typeof b.thinking === 'string') {facts.push({ kind: 'thinking', messageRef: message.id, block: index, text: b.thinking, phase: 'complete' });}
      if (b.type === 'tool_use' && typeof b.id === 'string' && typeof b.name === 'string') {facts.push({ kind: 'tool', messageRef: message.id, toolRef: b.id, name: b.name, input: b.input });}
      index += 1;
    }
    this.completeIndex.set(message.id, index);
    return facts;
  }
  private toolResults(message: Record<string, unknown>): Fact[] {
    if (!Array.isArray(message.content)) {return [];}
    return message.content.flatMap((value) => {
      const b = record(value);
      return b.type === 'tool_result' && typeof b.tool_use_id === 'string' ? [{ kind: 'tool-result' as const, toolRef: b.tool_use_id, content: b.content, isError: b.is_error === true }] : [];
    });
  }
  private result(m: Record<string, unknown>): ReturnType<Normalizer['normalize']> {
    const usage = record(m.usage);
    const facts: Fact[] = [{ kind: 'usage',
      ...(typeof usage.input_tokens === 'number' ? { inputTokens: usage.input_tokens } : {}),
      ...(typeof usage.output_tokens === 'number' ? { outputTokens: usage.output_tokens } : {}),
      ...(typeof m.total_cost_usd === 'number' ? { cumulativeCostUsd: m.total_cost_usd } : {}),
    }];
    if (m.subtype === 'success') {return { facts, terminal: m.is_error === true ? 'failed' : 'succeeded' };}
    if (['error_during_execution', 'error_max_turns', 'error_max_budget_usd', 'error_max_structured_output_retries'].includes(String(m.subtype))) {return { facts, terminal: 'failed', failure: 'provider-failure' };}
    return { facts, terminal: 'unknown', failure: 'unsupported' };
  }
}

import { randomUUID } from 'node:crypto';
import { decodeClaudePromptSuggestion } from '../../../native-prompt-suggestions/adapters/claude-sdk.ts';
import { eligibleNativeInput, offerNativeSuggestion } from '../../../native-prompt-suggestions/core/policy.ts';
import type { CanUseTool, Options, Query, SDKUserMessage } from '@anthropic-ai/claude-agent-sdk';
import type { CloseReceipt, Event, EventPayload, FailureCode, Handoff, Input, InteractionReply, Reply, Session } from '@agent-teams/provider-session-contracts';
import { compatibility, options, SDK_REVISION } from './config.ts';
import type { ClaudeConfig } from './config.ts';
import { toolBindingHook } from './tool-binding.ts';
import type { ForegroundToolOwner } from './tool-binding.ts';
import { ClaudeSubagents } from './subagents.ts';
import { ClaudeCapture } from './capture.ts';
import { Interactions } from './interactions.ts';
import { Normalizer, OutputLimitError, record } from './normalize.ts';
import { captureClaudeCommands, claudeCommandName, claudeLegacyReviewContent, claudeLocalCommandText, projectClaudeCommands, resolveClaudeCommand } from './commands.ts';
import type { ClaudeCommandDescription } from './commands.ts';
import { bounded, deferred, EventFeed } from '../provider-session-io/io.ts';
import { fail } from './primitives.ts';
import { AttachmentFailure, assertSerializedAttachments, prepareAttachments, snapshotInput, validateAttachments } from '../provider-session-io/attachments.ts';
import type { PreparedAttachment } from '../provider-session-io/attachments.ts';
export type QueryHandle = Pick<Query, 'interrupt' | 'close' | 'mcpServerStatus'> & Partial<Pick<Query, 'stopTask' | 'supportedCommands'>> & AsyncIterable<unknown>;
export type QueryFactory = (args: { prompt: AsyncIterable<SDKUserMessage>; options: Options }) => QueryHandle;
type PendingInput = { input: Input; handed: boolean; nativeRef: ReturnType<typeof randomUUID>; receipt: ReturnType<typeof deferred<Reply<Handoff>>>; interactionsCancelled: boolean; toolRevocation: AbortController; command?: ClaudeCommandDescription };
/** A complete successful main-thread result without foreground or restore provenance. */
function idleNativeSuccess(m: Record<string, unknown>, nativeSession: string): boolean {
  const numbers = [m.duration_ms, m.duration_api_ms, m.total_cost_usd];
  const objects = [m.usage, m.modelUsage];
  return m.type === 'result' && m.subtype === 'success' && m.is_error === false && m.session_id === nativeSession &&
    (m.parent_tool_use_id === null || m.parent_tool_use_id === undefined) &&
    [m.agent_id, m.resume_reason, m.user_message_uuid, m.user_message_uuids].every(value => value === undefined) &&
    typeof m.uuid === 'string' && m.uuid.length > 0 && typeof m.result === 'string' &&
    (m.stop_reason === null || typeof m.stop_reason === 'string') &&
    typeof m.num_turns === 'number' && Number.isSafeInteger(m.num_turns) && m.num_turns >= 0 &&
    numbers.every(value => typeof value === 'number' && Number.isFinite(value) && value >= 0) &&
    objects.every(value => value !== null && typeof value === 'object' && !Array.isArray(value)) &&
    Array.isArray(m.permission_denials);
}
export class ClaudeSession implements Session {
  readonly sessionRef: string;
  private state: 'open' | 'unavailable' | 'closed' = 'open';
  private readonly feed: EventFeed<Event>;
  private readonly normalizer: Normalizer;
  private readonly backgroundNormalizer: Normalizer;
  private readonly interactions: Interactions;
  private readonly query: QueryHandle;
  private readonly readLoop: Promise<void>;
  private readonly queued: PendingInput[] = [];
  private active: PendingInput | undefined;
  private readonly messageOwners = new Map<string, Input>();
  private readonly toolOwners = new Map<string, { input: Input; name: string }>();
  private toolOwnershipChanged = deferred<void>();
  private pendingToolOwners = 0;
  private readonly nativeToolIdentities = new Map<string, { nativeInput: string; name: string }>();
  private streamRef: string | undefined;
  private foregroundBound = false;
  private turnBytes = 0;
  private turnEvents = 0;
  private knownTerminal: Extract<Event, { kind: 'result' }> | undefined;
  /** The SDK emits prompt_suggestion after result, when active has already retired. */
  private lastSuccessfulInput: Input | undefined;
  private suggestionOwner: Input | undefined;
  // The SDK has no input ID on suggestions; ambiguous ownership cannot recover in this Query.
  private suggestionsUncertain = false;
  private wakeup = deferred<void>();
  private readonly inputClosed = deferred<void>();
  private control: Promise<Reply<{ requested: true; terminal: 'unconfirmed' }>> | undefined;
  private closing?: Promise<CloseReceipt>;
  private readiness: Promise<Reply<void>> | undefined;
  private failure: FailureCode | undefined;
  private readonly config: ClaudeConfig;
  private readonly nativeSession: string;
  private readonly subagents: ClaudeSubagents | undefined;
  private readonly capture: ClaudeCapture | undefined;
  private commands: readonly ClaudeCommandDescription[] = [];
  constructor(config: ClaudeConfig, nativeSession: string, restore: boolean, factory: QueryFactory) {
    this.config = config; this.nativeSession = nativeSession;
    this.sessionRef = config.sessionRef;
    this.feed = new EventFeed(config.limits.outputEvents, config.limits.outputBytes);
    this.normalizer = new Normalizer(config.limits.outputBytes);
    this.backgroundNormalizer = new Normalizer(config.limits.outputBytes);
    this.interactions = new Interactions(config.limits.pendingInteractions, config.limits.timeoutMs, (event, childRef, toolRef): void | Promise<void> => {
      if (!this.active || this.active.interactionsCancelled || this.state !== 'open') { this.interactions.cancel(); return; }
      if (childRef !== undefined) {return this.childInteraction(event, childRef, toolRef);}
      this.emit(event, this.active.input);
    });
    const currentToolOwner = (toolId: string, toolName: string) => {
