      "originalContent": "name: CI\non:\n  pull_request:\n  workflow_dispatch:\npermissions:\n  contents: read\nconcurrency:\n  group: ci-${{ github.event.pull_request.number || github.ref }}\n  cancel-in-progress: true\njobs:\n  check:\n    runs-on: ubuntu-24.04\n    timeout-minutes: 20\n    strategy:\n      fail-fast: false\n      matrix:\n        node: ['24.21.0', '26.11.1']\n    steps:\n      - uses: actions/checkout@d23441a48e516b6c34aea4fa41551a30e30af803 # v6\n        with:\n          ref: ${{ github.event.pull_request.head.sha || github.sha }}\n          persist-credentials: false\n      - name: Setup Node24 Corepack source\n        uses: actions/setup-node@249970729cb0ef3589644e2896645e5dc5ba9c38 # v6\n        with:\n          node-version: 24.21.0\n          package-manager-cache: false\n      - name: Setup selected Node\n        uses: actions/setup-node@249970729cb0ef3589644e2896645e5dc5ba9c38 # v6\n        with:\n          node-version: ${{ matrix.node }}\n          package-manager-cache: false\n      - name: Select pinned pnpm through selected Node\n        shell: bash\n        run: |\n          set -euo pipefail\n          selectedNode=\"$(node -p 'process.execPath')\"\n          corepackJs=\"$RUNNER_TOOL_CACHE/node/24.21.0/$(node -p 'process.arch')/lib/node_modules/corepack/dist/corepack.js\"\n          test -f \"$corepackJs\"\n          mkdir -p \"$RUNNER_TEMP/toolchain/bin\" \"$RUNNER_TEMP/toolchain/corepack\"\n          printf '#!/bin/sh\\nexec \"%s\" \"%s\" pnpm@11.18.0 \"$@\"\\n' \"$selectedNode\" \"$corepackJs\" > \"$RUNNER_TEMP/toolchain/bin/pnpm\"\n          chmod 755 \"$RUNNER_TEMP/toolchain/bin/pnpm\"\n          printf '%s\\n' \"$RUNNER_TEMP/toolchain/bin\" >> \"$GITHUB_PATH\"\n          printf 'COREPACK_HOME=%s\\n' \"$RUNNER_TEMP/toolchain/corepack\" >> \"$GITHUB_ENV\"\n          COREPACK_HOME=\"$RUNNER_TEMP/toolchain/corepack\" \"$selectedNode\" \"$corepackJs\" pnpm@11.18.0 --version\n      - name: Install exact dependency graph\n        run: pnpm install --frozen-lockfile --ignore-scripts\n      - name: Types, controlled tests and packed consumers\n        env:\n          # Retain the SAME exact bytes installed by the package-consumer test.\n          AGENT_TEAMS_PROVIDER_PACK_TEST_RETAIN_DIR: ${{ runner.temp }}/checked-v2-spi\n        run: pnpm check\n      - name: Record exact-head checked archives (not a Host qualification)\n        if: matrix.node == '24.21.0'\n        shell: bash\n        env:\n          EXPECTED_HEAD: ${{ github.event.pull_request.head.sha || github.sha }}\n        run: |\n          node --input-type=module <<'NODE'\n          import { createHash } from 'node:crypto'\n          import { execFileSync } from 'node:child_process'\n          import { readFileSync, readdirSync, writeFileSync } from 'node:fs'\n          import { join } from 'node:path'\n          const root = join(process.env.RUNNER_TEMP, 'checked-v2-spi')\n          const names = readdirSync(root).filter(name => name.endsWith('.tgz')).sort()\n          if (names.length !== 2 ||\n              names.filter(name => name.startsWith('agent-teams-provider-implementations-')).length !== 1 ||\n              names.filter(name => name.startsWith('agent-teams-provider-session-contracts-')).length !== 1)\n            throw Error('expected_exact_two_consumer_checked_archives')\n          const head = execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim()\n          if (head !== process.env.EXPECTED_HEAD) throw Error('unexpected_checkout_head')\n          const packages = names.map(name => {\n            const data = readFileSync(join(root, name))\n            return { file: name, bytes: data.length,\n              sha256: createHash('sha256').update(data).digest('hex') }\n          })\n          const receipt = { schemaVersion: 1, sourceCommit: head, packages,\n            qualification: 'source-and-packed-consumer-only',\n            nativeHostQualified: false, packagedElectronQualified: false }\n          writeFileSync(join(root, 'receipt.json'), JSON.stringify(receipt, null, 2) + String.fromCharCode(10))\n          console.log(JSON.stringify(receipt))\n          NODE\n      - name: Upload TEST-only exact-HEAD checked provider and Session SPI archives\n        if: matrix.node == '24.21.0'\n        uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02 # v4.6.2\n        with:\n          name: opencode-v2-spi-consumer-checked-${{ github.event.pull_request.head.sha || github.sha }}\n          path: ${{ runner.temp }}/checked-v2-spi/\n          if-no-files-found: error\n          retention-days: 7\n"
