      "originalContent": "name: Native prompt suggestions - Claude TEST E2E\n\non:\n  pull_request:\n    types: [opened, synchronize, reopened, ready_for_review]\n    paths:\n      - \"scripts/native-prompt-suggestions-claude.mjs\"\n      - \".github/workflows/native-prompt-suggestions-claude.yml\"\n  workflow_dispatch:\n\npermissions:\n  contents: read\n\nconcurrency:\n  group: native-claude-suggestions-${{ github.event.pull_request.number || github.ref }}\n  cancel-in-progress: true\n\njobs:\n  claude-native-suggestion:\n    if: github.event_name != 'pull_request' || github.event.pull_request.draft == false\n    runs-on: ubuntu-24.04\n    timeout-minutes: 8\n    steps:\n      - uses: actions/checkout@d23441a48e516b6c34aea4fa41551a30e30af803 # v6\n        with:\n          ref: ${{ github.event.pull_request.head.sha || github.sha }}\n          persist-credentials: false\n      - uses: actions/setup-node@249970729cb0ef3589644e2896645e5dc5ba9c38 # v6\n        with:\n          node-version: 24.21.0\n          package-manager-cache: false\n      - name: Install pinned provider SDK without credentials or install scripts\n        shell: bash\n        run: |\n          set -euo pipefail\n          corepack enable\n          corepack pnpm --version\n          corepack pnpm install --frozen-lockfile --ignore-scripts\n      - name: Actual SDK / native Claude Code CLI, locally scripted inference only\n        shell: bash\n        env:\n          NATIVE_SUGGESTIONS_CLAUDE_RECEIPT: ${{ github.workspace }}/native-prompt-suggestions-claude-receipt.json\n        run: |\n          set -euo pipefail\n          node --check scripts/native-prompt-suggestions-claude.mjs\n          node scripts/native-prompt-suggestions-claude.mjs\n      - name: Upload only bounded TEST receipt, never raw inference or credentials\n        if: always()\n        uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02 # v4\n        with:\n          name: claude-native-prompt-suggestions-TEST-${{ github.sha }}\n          retention-days: 7\n          if-no-files-found: warn\n          path: native-prompt-suggestions-claude-receipt.json\n"
    },
