      "originalContent": "name: Native prompt suggestions - Codex TEST E2E\n\non:\n  pull_request:\n    types: [opened, synchronize, reopened, ready_for_review]\n    paths:\n      - \"packages/provider-implementations/src/features/native-prompt-suggestions/**\"\n      - \"packages/provider-implementations/src/features/provider-session-implementation/adapters/codex-protocol/**\"\n      - \"packages/provider-implementations/src/features/provider-session-implementation/adapters/claude-sdk/**\"\n      - \"scripts/native-prompt-suggestions-codex.mjs\"\n      - \".github/workflows/native-prompt-suggestions.yml\"\n  workflow_dispatch:\n\npermissions:\n  contents: read\n\nconcurrency:\n  group: native-prompt-suggestions-${{ github.event.pull_request.number || github.ref }}\n  cancel-in-progress: true\n\njobs:\n  codex-native-sample:\n    if: github.event_name != 'pull_request' || github.event.pull_request.draft == false\n    runs-on: ubuntu-24.04\n    timeout-minutes: 12\n    steps:\n      - uses: actions/checkout@d23441a48e516b6c34aea4fa41551a30e30af803 # v6\n        with:\n          ref: ${{ github.event.pull_request.head.sha || github.sha }}\n          persist-credentials: false\n      - uses: actions/setup-node@249970729cb0ef3589644e2896645e5dc5ba9c38 # v6\n        with:\n          node-version: 24.21.0\n          package-manager-cache: false\n      - name: Select one official native Codex CLI in a disposable runner prefix\n        shell: bash\n        env:\n          npm_config_audit: \"false\"\n          npm_config_fund: \"false\"\n        run: |\n          set -euo pipefail\n          mkdir -p \"$RUNNER_TEMP/native-next-prompt-codex\" \"$RUNNER_TEMP/native-next-prompt-home\"\n          HOME=\"$RUNNER_TEMP/native-next-prompt-home\" npm install \\\n            --prefix \"$RUNNER_TEMP/native-next-prompt-codex\" --no-save \\\n            --package-lock=true --ignore-scripts --no-audit --no-fund \\\n            @openai/codex@0.166.0\n          HOME=\"$RUNNER_TEMP/native-next-prompt-home\" npm ls \\\n            --prefix \"$RUNNER_TEMP/native-next-prompt-codex\" --depth=0 @openai/codex\n      - name: Verify actual App Server native turn and ephemeral fork (no vendor subscription)\n        shell: bash\n        env:\n          NATIVE_SUGGESTIONS_CODEX_PREFIX: ${{ runner.temp }}/native-next-prompt-codex\n          NATIVE_SUGGESTIONS_RECEIPT: ${{ github.workspace }}/native-prompt-suggestions-codex-receipt.json\n        run: |\n          set -euo pipefail\n          node --check scripts/native-prompt-suggestions-codex.mjs\n          node scripts/native-prompt-suggestions-codex.mjs\n      - name: Upload bounded TEST evidence (not vendor or Desktop qualification)\n        if: always()\n        uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02 # v4\n        with:\n          name: codex-native-prompt-suggestions-TEST-${{ github.sha }}\n          retention-days: 7\n          if-no-files-found: warn\n          path: native-prompt-suggestions-codex-receipt.json\n"
