      "sha256": "971cad0c24cb60cdcfb4dd344d91b70d9527ebe01bc88f1495dc09bded25517a",
      "exact": true,
      "originalContent": "name: OpenCode V2 native E2E qualification (TEST only)\n\non:\n  pull_request:\n    paths:\n      # The pinned dependency graph and shared Session SPI define the\n      # effective native driver contract just as much as its V2 codec does.\n      - 'package.json'\n      - 'pnpm-lock.yaml'\n      - 'packages/provider-implementations/package.json'\n      - 'packages/provider-session-contracts/package.json'\n      - 'packages/provider-session-contracts/src/**'\n      # Source changes to the private V2 wire, decoder or projection must\n      # invalidate the native contract proof, not only harness edits.\n      - 'packages/provider-implementations/src/features/provider-session-implementation/adapters/opencode-protocol/v2-*.ts'\n      # The V2 driver also runs through this shared Session SPI engine and\n      # bounded I/O. Changes here must invalidate native V2 receipts as well.\n      - 'packages/provider-implementations/src/features/provider-session-implementation/adapters/opencode-protocol/driver-session.ts'\n      - 'packages/provider-implementations/src/features/provider-session-implementation/adapters/opencode-protocol/driver-protocol.ts'\n      - 'packages/provider-implementations/src/features/provider-session-implementation/adapters/opencode-protocol/input-window-capture.ts'\n      - 'packages/provider-implementations/src/features/provider-session-implementation/adapters/provider-session-io/io.ts'\n      - 'packages/provider-implementations/src/features/provider-session-implementation/adapters/provider-session-io/attachments.ts'\n      - 'packages/provider-implementations/tests/features/provider-session-implementation/opencode-protocol/v2-*.ts'\n      - scripts/native-v2-readonly-proof.mjs\n      - scripts/native-v2-model-candidate.mjs\n      - scripts/verify-native-v2-cli-hold.mjs\n      - scripts/native-v2-embedded-proof.mjs\n      - scripts/native-v2-spi-proof.mjs\n      - scripts/verify-native-v2-embedded-floor-hold.mjs\n      - scripts/verify-native-v2-interrupt-proof.mjs\n      - scripts/native-v2-mcp-proof.mjs\n      - scripts/native-v2-mcp-proof.test.mjs\n      - scripts/verify-native-v2-receipt-safety.mjs\n      - scripts/verify-native-v2-receipt-safety.test.mjs\n      - .github/workflows/native-v2-readonly.yml\n  workflow_dispatch:\n\npermissions:\n  contents: read\n\nconcurrency:\n  group: native-v2-discovery-${{ github.event.pull_request.number || github.ref }}\n  cancel-in-progress: true\n\njobs:\n  native-v2-test:\n    runs-on: ${{ matrix.os }}\n    timeout-minutes: 10\n    strategy:\n      fail-fast: false\n      matrix:\n        include:\n          # Actual 2.1.4 Session SPI over owned TEST HTTP server + persistent events.\n          # Product Host/graph/process and packaged Desktop remain separate gates.\n          - { os: ubuntu-24.04, proof: embedded-target-spi }\n          - { os: macos-15, proof: embedded-target-spi }\n          - { os: macos-15-intel, proof: embedded-target-spi }\n          - { os: windows-2022, proof: embedded-target-spi }\n          - { os: windows-11-arm, proof: embedded-target-spi }\n          - { os: ubuntu-24.04, proof: lifecycle }\n          - { os: ubuntu-24.04, proof: model }\n          - { os: ubuntu-24.04, proof: embedded }\n          - { os: ubuntu-24.04, proof: embedded-model }\n          - { os: ubuntu-24.04, proof: embedded-interrupt }\n          # Exact pinned 2.0.21 private-Driver MCP TEST on all five native OS tuples.\n          # No production Host process custody or 2.1.4 Driver admission implied.\n          - { os: ubuntu-24.04, proof: embedded-mcp }\n          - { os: ubuntu-24.04, proof: embedded-target-mcp }\n          - { os: ubuntu-24.04, proof: embedded-floor }\n          - { os: ubuntu-24.04, proof: embedded-target }\n          - { os: ubuntu-24.04, proof: embedded-target-model }\n          # TEST-only exact SDK 2.1.4 active stream cancellation and cold no-replay.\n          # Separate from pinned 2.0.21: neither is a production Driver admission.\n          - { os: ubuntu-24.04, proof: embedded-target-interrupt }\n          # Discovery only: actual local fake-model tool call, policy hard-deny,\n          # and an outside-workspace canary. Not a Host/production PASS.\n          - { os: ubuntu-24.04, proof: embedded-target-tool }\n          # Actual 2.0.21 private-driver pin: native tool blocked by explicit\n          # session external_directory deny, not the newer config policy.\n          - { os: ubuntu-24.04, proof: embedded-pinned-tool }\n          - { os: macos-15, proof: embedded }\n          - { os: macos-15, proof: embedded-model }\n          - { os: macos-15, proof: embedded-interrupt }\n          - { os: macos-15, proof: embedded-target-interrupt }\n          # Native SDK 2.1.4 offline model terminal, durable pagination and cold no-replay.\n          - { os: macos-15, proof: embedded-target-model }\n          - { os: macos-15, proof: embedded-pinned-tool }\n          - { os: macos-15, proof: embedded-target-tool }\n          - { os: macos-15, proof: embedded-target-mcp }\n          - { os: macos-15, proof: embedded-mcp }\n          # GitHub-hosted macos-15 is Apple Silicon; macos-15-intel is x64.\n          - { os: macos-15-intel, proof: embedded }\n          - { os: macos-15-intel, proof: embedded-model }\n          - { os: macos-15-intel, proof: embedded-interrupt }\n          - { os: macos-15-intel, proof: embedded-target-interrupt }\n          - { os: macos-15-intel, proof: embedded-target-model }\n          - { os: macos-15-intel, proof: embedded-pinned-tool }\n          - { os: macos-15-intel, proof: embedded-target-tool }\n          # 2.1.4 MCP custody/readback on Intel macOS as well as Apple Silicon.\n          - { os: macos-15-intel, proof: embedded-target-mcp }\n          - { os: macos-15-intel, proof: embedded-mcp }\n          - { os: windows-2022, proof: embedded }\n          - { os: windows-2022, proof: embedded-model }\n          - { os: windows-2022, proof: embedded-interrupt }\n          - { os: windows-2022, proof: embedded-target-interrupt }\n          - { os: windows-2022, proof: embedded-pinned-tool }\n          - { os: windows-2022, proof: embedded-target-tool }\n          - { os: windows-2022, proof: embedded-target-mcp }\n          - { os: windows-2022, proof: embedded-mcp }\n          # Windows 11 ARM64 is a separate native SDK tuple, not Server 2022 x64.\n          - { os: windows-11-arm, proof: embedded-target-mcp }\n          - { os: windows-11-arm, proof: embedded-mcp }\n          - { os: windows-11-arm, proof: embedded-target-interrupt }\n          - { os: windows-11-arm, proof: embedded-target-model }\n          # Independently prove 2.1.4 tool.use/external_directory hard-deny on\n          # Windows ARM64; MCP/interrupt evidence alone cannot qualify policy.\n          - { os: windows-11-arm, proof: embedded-target-tool }\n          # Private Driver still pins 2.0.21: independently exercise its native\n          # interrupted-stream/cold-restart and built-in read deny/allow on ARM64.\n          # TEST-only evidence; no platform/default/production qualification.\n          - { os: windows-11-arm, proof: embedded-interrupt }\n          - { os: windows-11-arm, proof: embedded-pinned-tool }\n          - { os: windows-2022, proof: embedded-target }\n          - { os: windows-2022, proof: embedded-target-model }\n    steps:\n      - uses: actions/checkout@d23441a48e516b6c34aea4fa41551a30e30af803 # v6\n        with:\n          ref: ${{ github.event.pull_request.head.sha || github.sha }}\n          persist-credentials: false\n      - uses: actions/setup-node@249970729cb0ef3589644e2896645e5dc5ba9c38 # v6\n        with:\n          node-version: 24.21.0\n          package-manager-cache: false\n      - name: Build exact workspace provider for native Session SPI\n        if: matrix.proof == 'embedded-target-spi'\n        shell: bash\n        run: |\n          set -euo pipefail\n          npm exec --yes --package=pnpm@11.18.0 -- pnpm install --frozen-lockfile --ignore-scripts\n          npm exec --yes --package=pnpm@11.18.0 -- pnpm build\n      - name: Validate native TEST harness syntax\n        run: |\n          node --check scripts/native-v2-readonly-proof.mjs\n          node --check scripts/native-v2-model-candidate.mjs\n          node --check scripts/verify-native-v2-cli-hold.mjs\n          node --check scripts/native-v2-embedded-proof.mjs\n          node --check scripts/native-v2-spi-proof.mjs\n          node --check scripts/verify-native-v2-embedded-floor-hold.mjs\n          node --check scripts/verify-native-v2-interrupt-proof.mjs\n          node --check scripts/native-v2-mcp-proof.mjs\n          node --test scripts/native-v2-mcp-proof.test.mjs\n          node --check scripts/verify-native-v2-receipt-safety.mjs\n          node --test scripts/verify-native-v2-receipt-safety.test.mjs\n      - name: Install exact official V2 CLI into isolated test prefix\n        if: matrix.proof == 'lifecycle' || matrix.proof == 'model'\n        shell: bash\n        env:\n          npm_config_audit: 'false'\n          npm_config_fund: 'false'\n        run: |\n          set -euo pipefail\n          mkdir -p \"$RUNNER_TEMP/opencode-v2-native/npm\" \"$RUNNER_TEMP/opencode-v2-native/install-home\"\n          HOME=\"$RUNNER_TEMP/opencode-v2-native/install-home\" npm install \\\n            --prefix \"$RUNNER_TEMP/opencode-v2-native/npm\" \\\n            --no-save --package-lock=true --ignore-scripts --no-audit --no-fund @opencode/cli@2.0.21\n          npm ls --prefix \"$RUNNER_TEMP/opencode-v2-native/npm\" --depth=0 @opencode/cli\n      - name: Install exact pinned embedded V2 SDK without install scripts\n        if: startsWith(matrix.proof, 'embedded')\n        shell: bash\n        env:\n          npm_config_audit: 'false'\n          npm_config_fund: 'false'\n        run: |\n          set -euo pipefail\n          mkdir -p \"$RUNNER_TEMP/opencode-v2-embedded\"\n          npm install --prefix \"$RUNNER_TEMP/opencode-v2-embedded\" --no-save \\\n            --package-lock=true --ignore-scripts --no-audit --no-fund @opencode/sdk@${{ startsWith(matrix.proof, 'embedded-floor') && '2.0.0' || startsWith(matrix.proof, 'embedded-target') && '2.1.4' || '2.0.21' }}\n          npm ls --prefix \"$RUNNER_TEMP/opencode-v2-embedded\" --depth=0 @opencode/sdk\n      - name: TEST native binary, authenticated API and disposable session lifecycle\n        if: matrix.proof == 'lifecycle'\n        env:\n          OPENCODE_V2_TEST_NPM_ROOT: ${{ runner.temp }}/opencode-v2-native/npm/node_modules/@opencode\n          OPENCODE_V2_TEST_RECEIPT: ${{ github.workspace }}/native-v2-readonly-proof.json\n        run: node scripts/native-v2-readonly-proof.mjs\n      - name: Assert stock CLI native model terminal HOLD (expected negative control)\n        if: matrix.proof == 'model'\n        shell: bash\n        env:\n          OPENCODE_V2_TEST_NPM_ROOT: ${{ runner.temp }}/opencode-v2-native/npm/node_modules/@opencode\n          OPENCODE_V2_TEST_MODEL_RECEIPT: ${{ github.workspace }}/native-v2-model-candidate.json\n        run: |\n          set +e\n          node scripts/native-v2-model-candidate.mjs\n          status=$?\n          set -e\n          if [ \"$status\" -ne 1 ]; then\n            echo \"::error::Stock CLI changed behavior or did not execute; review native evidence before qualification\"\n            exit 1\n          fi\n          node scripts/verify-native-v2-cli-hold.mjs\n      - name: Assert published SDK 2.0.0 Node ESM HOLD (expected negative control)\n        if: matrix.proof == 'embedded-floor'\n        shell: bash\n        env:\n          OPENCODE_V2_EMBEDDED_NPM_PREFIX: ${{ runner.temp }}/opencode-v2-embedded\n          OPENCODE_V2_EMBEDDED_RECEIPT: ${{ github.workspace }}/native-v2-embedded-floor-proof.json\n          OPENCODE_V2_EMBEDDED_VERSION: '2.0.0'\n          OPENCODE_V2_EMBEDDED_MODEL_PROOF: '0'\n          OPENCODE_V2_TEST_EXPECTED_PLATFORM: 'linux-x64'\n        run: |\n          set +e\n          node scripts/native-v2-embedded-proof.mjs\n          status=$?\n          set -e\n          if [ \"$status\" -ne 1 ]; then\n            echo \"::error::Published floor SDK behavior changed; requalify before any adoption\"\n            exit 1\n          fi\n          node scripts/verify-native-v2-embedded-floor-hold.mjs\n      - name: TEST embedded V2 persistent event log through cold host restart\n        if: startsWith(matrix.proof, 'embedded') && matrix.proof != 'embedded-floor' && matrix.proof != 'embedded-interrupt' && matrix.proof != 'embedded-target-interrupt' && matrix.proof != 'embedded-mcp' && matrix.proof != 'embedded-target-mcp' && matrix.proof != 'embedded-target-spi'\n        env:\n          OPENCODE_V2_EMBEDDED_NPM_PREFIX: ${{ runner.temp }}/opencode-v2-embedded\n          OPENCODE_V2_EMBEDDED_RECEIPT: ${{ github.workspace }}/native-v2-${{ matrix.proof }}-proof.json\n          OPENCODE_V2_EMBEDDED_MODEL_PROOF: ${{ (endsWith(matrix.proof, '-model') || endsWith(matrix.proof, '-tool') || endsWith(matrix.proof, '-interrupt')) && '1' || '0' }}\n          OPENCODE_V2_EMBEDDED_INTERRUPT_PROOF: ${{ endsWith(matrix.proof, '-interrupt') && '1' || '0' }}\n          OPENCODE_V2_EMBEDDED_TOOL_PROOF: ${{ endsWith(matrix.proof, '-tool') && '1' || '0' }}\n          OPENCODE_V2_EMBEDDED_VERSION: ${{ startsWith(matrix.proof, 'embedded-target') && '2.1.4' || '2.0.21' }}\n          OPENCODE_V2_TEST_EXPECTED_PLATFORM: ${{ matrix.os == 'macos-15' && 'darwin-arm64' || matrix.os == 'macos-15-intel' && 'darwin-x64' || matrix.os == 'windows-2022' && 'win32-x64' || matrix.os == 'windows-11-arm' && 'win32-arm64' || 'linux-x64' }}\n        run: node scripts/native-v2-embedded-proof.mjs\n      - name: TEST embedded versioned active-interrupt HTTP cancel and cold no-replay\n        if: matrix.proof == 'embedded-interrupt' || matrix.proof == 'embedded-target-interrupt'\n        env:\n          OPENCODE_V2_EMBEDDED_NPM_PREFIX: ${{ runner.temp }}/opencode-v2-embedded\n          OPENCODE_V2_EMBEDDED_RECEIPT: ${{ github.workspace }}/native-v2-${{ matrix.proof }}-proof.json\n          OPENCODE_V2_EMBEDDED_MODEL_PROOF: '1'\n          OPENCODE_V2_EMBEDDED_INTERRUPT_PROOF: '1'\n          OPENCODE_V2_EMBEDDED_VERSION: ${{ matrix.proof == 'embedded-target-interrupt' && '2.1.4' || '2.0.21' }}\n          OPENCODE_V2_TEST_EXPECTED_PLATFORM: ${{ matrix.os == 'macos-15' && 'darwin-arm64' || matrix.os == 'macos-15-intel' && 'darwin-x64' || matrix.os == 'windows-2022' && 'win32-x64' || matrix.os == 'windows-11-arm' && 'win32-arm64' || 'linux-x64' }}\n        run: |\n          node scripts/native-v2-embedded-proof.mjs\n          node scripts/verify-native-v2-interrupt-proof.mjs\n      - name: TEST embedded V2 local MCP stdio handshake and owned teardown\n        if: matrix.proof == 'embedded-mcp' || matrix.proof == 'embedded-target-mcp'\n        env:\n          OPENCODE_V2_EMBEDDED_NPM_PREFIX: ${{ runner.temp }}/opencode-v2-embedded\n          OPENCODE_V2_MCP_RECEIPT: ${{ github.workspace }}/native-v2-${{ matrix.proof }}-proof.json\n          OPENCODE_V2_MCP_VERSION: ${{ matrix.proof == 'embedded-target-mcp' && '2.1.4' || '2.0.21' }}\n          OPENCODE_V2_TEST_EXPECTED_PLATFORM: ${{ matrix.os == 'macos-15' && 'darwin-arm64' || matrix.os == 'macos-15-intel' && 'darwin-x64' || matrix.os == 'windows-2022' && 'win32-x64' || matrix.os == 'windows-11-arm' && 'win32-arm64' || 'linux-x64' }}\n        run: node scripts/native-v2-mcp-proof.mjs\n      - name: TEST native 2.1.4 Session SPI model, MCP permission, interrupt and cold restore\n        if: matrix.proof == 'embedded-target-spi'\n        env:\n          OPENCODE_V2_EMBEDDED_NPM_PREFIX: ${{ runner.temp }}/opencode-v2-embedded\n          OPENCODE_V2_SPI_RECEIPT: ${{ github.workspace }}/native-v2-embedded-target-spi-proof.json\n          OPENCODE_V2_TEST_EXPECTED_PLATFORM: ${{ matrix.os == 'macos-15' && 'darwin-arm64' || matrix.os == 'macos-15-intel' && 'darwin-x64' || matrix.os == 'windows-2022' && 'win32-x64' || matrix.os == 'windows-11-arm' && 'win32-arm64' || 'linux-x64' }}\n        run: node scripts/native-v2-spi-proof.mjs\n      - name: Refuse unsafe native TEST receipts before artifact publication\n        id: receipt_safety\n        if: always()\n        env:\n          OPENCODE_V2_EXPECTED_TEST_PROOF: ${{ matrix.proof }}\n        run: node scripts/verify-native-v2-receipt-safety.mjs\n      - name: Upload actual runner receipt (including safe failed checks)\n        if: always() && steps.receipt_safety.outcome == 'success'\n        uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02 # v4.6.2\n        with:\n          name: opencode-v2-discovery-${{ matrix.os }}-${{ matrix.proof }}\n          if-no-files-found: warn\n          retention-days: 7\n          path: |\n            native-v2-readonly-proof.json\n            native-v2-model-candidate.json\n            native-v2-embedded-proof.json\n            native-v2-embedded-model-proof.json\n            native-v2-embedded-interrupt-proof.json\n            native-v2-embedded-target-interrupt-proof.json\n            native-v2-embedded-target-spi-proof.json\n            native-v2-embedded-mcp-proof.json\n            native-v2-embedded-target-mcp-proof.json\n            native-v2-embedded-floor-proof.json\n            native-v2-embedded-target-proof.json\n            native-v2-embedded-target-model-proof.json\n            native-v2-embedded-target-tool-proof.json\n            native-v2-embedded-pinned-tool-proof.json\n            ${{ runner.temp }}/opencode-v2-embedded/package-lock.json\n            ${{ runner.temp }}/opencode-v2-native/npm/package-lock.json\n"
    },
